      "date": "2026-09-01",
      "title": "Create Ceramic Birdhouses with Cynthia Mahner",
      "location": "Bay St. Louis",
      "category": "Arts & Culture",
      "description": "Create a charming ceramic birdhouse that is truly one of a kind!In this hands-on clay workshop, instructor Cynthia Mahner will guide students through building a decorative birdhouse using slabs of clay and a pattern. Students will learn how to roll, cut, and assemble clay pieces before adding creative details with textures, press molds, cutters, and sculpted designs.Tuesday, September 1 *1-4pRegister Today: https://tinyurl.com/CeramicBirdhousesAges 15+Students will decorate their birdhouses with colorful underglazes, giving each piece its own personality and style. Whether you prefer whimsical flowers, natural textures, bold patterns, or sculpted embellishments, this class offers plenty of opportunities to make your birdhouse uniquely yours.Perfect for beginners and experienced makers alike, this workshop is a fun way to explore ceramic hand-building techniques while creating a decorative piece you will be proud to display.All materials and tools will be provided. Students only need to bring their imagination!About the Instructor:Cynthia Mahner has studied with Regan Carney and Steve Barney and has continued developing her skills through independent exploration. After inheriting a pottery studio, Cynthia expanded her love of clay and enjoys sharing what she has learned through encouraging, hands-on creative experiences.",
