      "title": "7th Annual Booker Fest",
      "location": "Bay St. Louis",
      "category": "Dining",
      "description": "Celebrate Labor Day weekend with music, culture, community, and unforgettable Coast vibes at the 7th Annual Booker Fest at historic 100 Men Hall in Bay St. Louis, Mississippi. This beloved end-of-summer festival honors the Hall's rich musical legacy with three days of incredible live performances, great food, local libations, and the welcoming spirit that makes Bay St. Louis a must-visit destination.This year's lineup promises to be the funkiest Booker Fest yet, featuring an outstanding mix of regional and national talent, including The Rumble, Water Seed, Lost Bayou Ramblers, Joe Krown Trio +1 featuring Papa Mali, Maggie Koerner, Chris Vincent & The Raw Deals, and the St. Rose de Lima Gospel Choir.Enjoy a weekend packed with live music, authentic Coast hospitality, and delicious Cajun cuisine, including free Cajun jambalaya prepared by real Cajuns during Sunday's festival finale featuring the acclaimed Lost Bayou Ramblers.Festival ScheduleFriday, September 4 (Single-day ticket: $30)6 PM \u2013 Chris Vincent & The Raw Deals7 PM \u2013 The RumbleChef Gene Coia on siteSaturday, September 5 (Single-day ticket: $75)2 PM \u2013 St. Rose de Lima Gospel Choir3:30 PM \u2013 Maggie Koerner5:15 PM \u2013 Joe Krown Trio +1 featuring Papa Mali (Tribute to Booker)7 PM \u2013 Water SeedChef Gene Coia serving from 4 PM onwardSunday, September 6 (Single-day ticket: $30)2\u20134 PM \u2013 Lost Bayou RamblersFree Cajun JambalayaTicketsExperience the entire weekend with a Booker Fest Hall Pass, which includes admission to all festival events:Early Bird Hall Pass: $95 (available through August 10, 2026)Regular Hall Pass: $110Single-day tickets are also available.All tickets will be held at Will Call.Don't miss one of Coastal Mississippi's most authentic music experiences. Gather your friends, secure your Hall Pass, and join us at historic 100 Men Hall for a Labor Day weekend filled with music, food, culture, and community at Booker Fest 2026! Tickets are on sale now.",
