      "location": "Gulfport/Biloxi",
      "category": "Dining",
      "description": "Get ready for three days of beachside music, laid-back island vibes, and unforgettable Coast fun at the 8th Annual Biloxi Box Set Music Festival, happening September 10-12, 2026, at the South Beach Hotel & Suites in Biloxi, Mississippi!This popular beachfront festival brings together trop rock fans, Parrot Heads, and music lovers from across the region for a weekend of live entertainment and community spirit.Hosted by the Towns Around Biloxi Parrot Head Club, the Biloxi Box Set is one of the premier trop rock festivals on the Mississippi Gulf Coast, featuring performances from acclaimed regional and national artists inspired by the tropical sounds made famous by Jimmy Buffett.Event DetailsAdmission: $107.50 Weekend Registration | $55 Day Passes AvailableWebsite/Registration: https://www.tickettailor.com/events/townsaroundbiloxiparrotheadclubFestival entertainment takes place on the beach behind the South Beach Hotel & Suites. The festival area is reserved for registered attendees, but registration is open to everyone.Attendees who register will receive information on booking accommodations at a special group rate at the host hotel.Live Music LineupThursday, September 10, 20265PM - 7PM: Dave Freeman8PM - 11PM: Crow the CulpritFriday, September 11, 202611AM - 1PM: John Patti2PM - 4PM: Brent Burns & Bill Whyte5PM - 7PM: Kirstie Kraus & Danny Spiro8PM - 11PM: Donny Brewer Trio featuring John Patti & Dave FreemanSaturday, September 12, 202611AM - 1PM: Kitty Steadman2PM - 4PM: Gram Rea & Friends5PM - 7PM: Carrie Welling8PM - 11PM: Jonas Lorence BandEmcee: Greg DumasMore Than a Music FestivalThe Biloxi Box Set combines the best of live trop rock music, beachfront relaxation, and Coast hospitality. Throughout the weekend, guests can enjoy themed gatherings, connect with fellow Parrot Heads, and experience the vibrant atmosphere of one of Biloxi's most unique annual events.In addition to great music, the festival supports charitable initiatives through sponsorship and donation opportunities, making it a meaningful way to enjoy a weekend on the Mississippi Gulf Coast while giving back.Whether you're a longtime Jimmy Buffett fan, a dedicated Parrot Head, or simply looking for a unique Biloxi music festival experience, the Biloxi Box Set offers the perfect blend of entertainment, community, and Coastal fun!For updates and additional information, visit the Biloxi Box Set Facebook page or the official event registration site.Tell your friends, gather your crew, and join the PHun on Biloxi Beach!",
