      "description": "Jeff Foxworthy is one of America\u2019s most celebrated stand-up comedians and among the most successful comedy performers of all time. A best-selling comedy recording artist, multiple Grammy Award nominee, and author of more than 26 books, Foxworthy has entertained audiences for decades with his sharp observational humor and relatable storytelling. In 2014, he was inducted into the Georgia Music Hall of Fame in recognition of his outstanding contributions to entertainment.Known worldwide for his iconic \u201cYou Might Be a Redneck\u201d jokes, Foxworthy\u2019s comedy goes far beyond his signature routine. His hilarious take on family life, everyday experiences, and human nature has earned comparisons to Mark Twain for its wit, insight, and broad appeal.Event InformationFully seated showGuests must be 21 years of age or older to attendValid ID required for entryDon't miss your chance to see Jeff Foxworthy live for an unforgettable night of stand-up comedy, laughter, and classic American humor in Biloxi, Mississippi!",
