      "location": "Gulfport/Biloxi",
      "category": "Festival",
      "description": "Get ready, Biloxi! Jurassic Quest is stomping into town September 18-20 for an unforgettable dinosaur experience the whole family will love! Featuring North America's largest collection of moving, roaring, life-sized dinosaurs, this immersive walk-through event brings the prehistoric world to life with interactive attractions, fossil digs, dinosaur rides, and hands-on activities for all ages.Discover a Prehistoric Adventure Like No OtherStep back in time and embark on a Jurassic Quest where discovery awaits around every corner. Encounter towering dinosaurs, including the mighty Tyrannosaurus rex and the massive Spinosaurus, meet adorable baby dinosaurs, excavate fossils like a real paleontologist, and even train a raptor.Kids can burn off energy in giant bounce houses, enjoy interactive exhibits, and unleash their creativity in exciting LEGO\u00ae-themed play zones. Whether you're a lifelong dinosaur enthusiast or looking for a fun family outing, Jurassic Quest delivers an educational and entertaining experience unlike any other!Event HoursFriday: 1 PM - 8 PMSaturday: 8 AM - 6 PMSunday: 9 AM - 5 PMActivities & AttractionsLife-sized moving, roaring, and breathing dinosaursInteractive dinosaur exhibits and live showsMeet-and-greet opportunities with baby dinosaursDinosaur rides on life-sized giantsFossil dig experiencesRaptor training activitiesGiant bounce housesLEGO\u00ae-themed play areasFamily-friendly entertainment for all agesGet Your Tickets Before They Go Extinct!There's no better place to create lasting family memories than Jurassic Quest. From playing with baby dinos to excavating fossils and standing beneath towering prehistoric giants, every moment is packed with adventure.Don't miss one of the top family events in Biloxi this September. Purchase your Jurassic Quest tickets today and experience the dinosaurs before they go extinct!",
