      "title": "MSIM 41st Annual $10,000 Drawdown",
      "location": "Gulfport/Biloxi",
      "category": "Dining",
      "description": "Join the Maritime & Seafood Industry Museum's 41st Annual $10,000 Drawdown, one of the Mississippi Gulf Coast's premier fundraising events, on Saturday, September 19, in Biloxi, Mississippi!This exciting evening supports the Museum's mission to preserve and celebrate the rich maritime heritage and seafood industry of the Gulf Coast. Guests will enjoy a night of great food, drinks, entertainment, and the chance to win the grand prize of $10,000.The event begins at 6 p.m. at the Maritime & Seafood Industry Museum, located at 115 1st Street, Biloxi, MS, and features:Fresh seafood buffetOpen bar and cocktails$10,000 Drawdown prize opportunitySplit the Pot raffleSilent auction featuring unique items and experiencesThe online silent auction opens on August 19 and closes at 8 p.m. on event night. Participants can browse and bid online at www.event.gives/msimdrawdown26.Admission is included for two guests with each $100 ticket. Tickets are available through Museum supporters, at the Museum, or online at www.maritimemuseum.org.Whether you're hoping to win the grand prize, enjoy exceptional Gulf Coast seafood, or support one of the region's most treasured cultural institutions, the Drawdown offers a memorable evening for a great cause.For tickets and additional information, visit www.maritimemuseum.org or call (228) 435-6320.",
