      "location": "Gulfport/Biloxi",
      "category": "Arts & Culture",
      "description": "Get ready for one of the most exciting sporting events on the Mississippi Gulf Coast as Banana Ball comes to Biloxi, Mississippi, for two unforgettable nights at Keesler Federal Park on Friday, September 25, and Saturday, September 26, 2026!Presented in partnership with Coastal Mississippi, Visit Mississippi, and the Savannah Bananas, the event will feature The Firefighters and the Loco Beach Coconuts competing as part of the 2026 Banana Ball Championship League.Experience the Fast-Paced Fun of Banana BallMore than a baseball game, Banana Ball is a high-energy entertainment experience that combines athletics, comedy, music, and fan interaction. Known for its viral popularity and national media attention, Banana Ball has captivated audiences across the country with its unique rules and nonstop action.Fans can expect:Trick plays and incredible athletic performancesDancing players and crowd participationFast-paced gameplay with unique Banana Ball rulesFamily-friendly entertainment for all agesInteractive fan experiences and unforgettable momentsBanana Ball features distinctive rules designed to keep the action moving, including:No buntingTwo-hour game time limitFans catching foul balls record outsBatters can steal first baseOne-on-one tiebreaker showdowns if the game ends tiedA Must-See Biloxi Sporting EventWhether you're a lifelong baseball fan or simply looking for a fun night out, The Firefighters vs. Loco Beach Coconuts promises an action-packed experience unlike any traditional baseball game. From the first pitch to the final out, expect nonstop entertainment, excitement, and plenty of surprises.Don't miss your chance to see the wildly popular world of Banana Ball live in Coastal Mississippi!***Image Credit: FANS FIRST ENTERTAINMENT / ANNA ROUCH",
