      "location": "Gulfport/Biloxi",
      "category": "Dining",
      "description": "Travel Back To The 1980's with us at Mangiamo Italian Restaurant in Gulfport!Join us for, like, a totally awesome night! Travel back to the 1980's, when the mall was the place to see and be seen, the food court was everything, and your biggest decision was Orange Julius or Sbarro. Pull out your neon, acid-wash jeans, stirrup pants, leg warmers, and biggest teased hair because it's time to take a break from reality and relive the decade of excess! Enjoy a delicious three-course meal served with heaping helpings of comedy, mystery, and audience interaction. Dress in your favorite 80's fashion for our Costume Contest, sip something from the cash bar (so you don't even have to drink out of the water hose), and see if you can solve the murder before the killer gets away.Can you figure out whodunnit among this totally tubular cast of outrageous Gen X characters?Admission IncludesThree-Course MealNon-Alcoholic BeverageCash Bar AvailableCostume ContestCommemorative PhotoPrizes for Winning SleuthsTax & Gratuity Included MenuFirst Course: AppetizerHouse SaladSecond Course: Entr\u00e9e (Choose One)Spaghetti and meatballsLinguine Alfredo with choice of shrimp or chickenChicken parmeseanPenne ala vodkaThird Course: Dessert (Choose One)CannoliCheesecake",
