      "title": "Create N Take | Miniature Matchbox Shrines With Brittany Heskett",
      "location": "Bay St. Louis",
      "category": "Arts & Culture",
      "description": "Create meaningful mixed media art in this hands-on miniature shrine workshop with artist Brittany Heskett.Join us on Friday, October 2, from 6 p.m. to 8 p.m. for Create N Take: Miniature Matchbox Shrines, a unique mixed media art class where you'll transform ordinary matchboxes into beautiful keepsakes filled with memories, intentions, and personal meaning.In this engaging workshop, Brittany Heskett will guide participants in creating two one-of-a-kind miniature shrines using a variety of mixed-media materials, including inks, acrylic paints, vintage ephemera, found imagery, and decorative embellishments. These tiny works of art are perfect for preserving cherished memories, honoring meaningful symbols, or capturing personal wishes and intentions.Participants are encouraged to bring a small photo, a lock of hair, a miniature memento, or a meaningful object to incorporate into their creations. Prefer to start fresh? A wide selection of materials will be provided for inspiration.No prior art experience is necessary. Whether you're new to mixed media or an experienced creator, you'll enjoy experimenting with layering techniques, telling your story through art, and creating something uniquely your own.The workshop will conclude with an optional intention-setting activity, allowing participants to add a personal finishing touch to their miniature treasures.Event DetailsAges: 15+ (younger artists welcome when accompanied by a parent or guardian)MaterialsAll class materials are provided except:X-Acto (craft) knifePersonal photos, keepsakes, or mementos you'd like to includeRegister Todayhttps://tinyurl.com/MiniMatchboxShrinesDiscover the art of meaningful making and create two miniature matchbox shrines that fit in your palm while holding memories, dreams, and personal stories.",
