      "description": "Join The Arts, Hancock County in celebrating contemporary art, creative excellence, and diverse artistic voices at the 2nd Bi-Annual Juried Exhibition. This nationally focused exhibition brings together emerging and established artists from across the United States for a professionally curated showcase.Designed to highlight innovative contemporary artwork, this juried exhibition fosters meaningful connections between local artists and the broader national arts community. With a strong curatorial vision, it presents a dynamic collection reflecting today\u2019s evolving artistic landscape.Selected works will be featured in a high-visibility exhibition celebrating the depth, diversity, and vitality of contemporary art. The exhibition will run from October 9 through November 18, with an opening reception on October 9 from 5:30 to 8 p.m. Artists nationwide are invited to submit original work. More than $2,000 in cash awards will be presented, including 1st-, 2nd-, and 3rd-place prizes, as well as honorable mentions in each category.CALL FOR ARTISTS!Deadline: August 7, 2026The Arts, Hancock County is now accepting entries for the 2nd Bi-Annual Juried Art Exhibition. Whether you're an emerging artist or an established professional, this is an opportunity to share your work with collectors, art enthusiasts, and fellow artists from across the country. For eligibility, entry fees, and complete submission guidelines, visit https://tinyurl.com/2026-JuriedArtExhibition.",
