      "description": "Join us at Tony's Brick Oven Pizzeria for, like, a totally awesome night! Travel back to the 1980's, when the mall was the place to see and be seen, the food court was everything, and your biggest decision was Orange Julius or Sbarro. Pull out your neon, acid-wash jeans, stirrup pants, leg warmers, and biggest teased hair because it's time to take a break from reality and relive the decade of excess! Enjoy a delicious three-course meal served with heaping helpings of comedy, mystery, and audience interaction. Dress in your favorite 80's fashion for our Costume Contest, sip something from the cash bar (so you don't even have to drink out of the water hose), and see if you can solve the murder before the killer gets away.Can you figure out whodunnit among this totally tubular cast of outrageous Gen X characters?MENUAppetizer Tony\u2019s Garden Salad-Fresh garden greens with our house dressingHOUSE-MADE BREAD-Warm, freshly made Italian bread with herb-infused butterENTREEChoose OnePenne RosaPenne-pasta tossed in our creamy rosa sauce Choose Shrimp or Nonna\u2019s MeatballsChicken or Shrimp Alfredo-Fettuccine tossed in our rich, creamy Alfredo sauce. Choose Chicken or ShrimpLasagna-Layers of pasta, cheese, meat sauce and Italian sausageEggplant Lasagna-Layers of tender eggplant, pasta, cheese and our Italian-inspired sauceDESSERT Choose One Classic Tiramisu-Traditional Italian dessert with coffee, mascarpone and cocoaItalian Rum Cake-A delicious Italian-style cake with a touch of rumBuon Appetito!Made with love, served with Italian tradition.Admission Includes:Three-Course MealNon-Alcoholic BeverageCash Bar AvailableCostume ContestCommemorative PhotoPrizes for Winning SleuthsTax & Gratuity Included",
