      "location": "Gulfport/Biloxi",
      "category": "Dining",
      "description": "Step into a world of retro-futuristic glamour at the 16th Annual Moonlight Masquerade Gala, one of the Mississippi Gulf Coast\u2019s most anticipated Halloween fundraising events. Prepare for an unforgettable evening of stars, saucers, and sequins as guests gather for a cosmic celebration supporting the vital work of the Gulf Coast Center for Nonviolence.Enjoy an extraordinary night featuring live music, handcrafted cocktails, delicious food, and dazzling entertainment. Indulge in hors d'oeuvres, small plates, charcuterie selections, and a buffet while mingling with fellow guests in an atmosphere filled with interstellar intrigue and vintage sci-fi elegance.The evening also includes a silent auction, tarot readings, and a costume contest, making this a Halloween gala that's truly out of this world! Whether you arrive in cosmic couture, masquerade attire, or classic cocktail wear, you'll be part of a memorable night dedicated to raising funds for survivors and families served by the Gulf Coast Center for Nonviolence.Event HighlightsLive musicHors d'oeuvres, small plates, charcuterie, and buffetSignature cocktailsSilent auctionTarot readingsCostume contestRetro-futuristic Halloween themeAdmission$85 per person$150 per coupleAges 21 and olderJoin us for an elegant Halloween evening where glamour meets philanthropy, and every ticket supports the mission of the Gulf Coast Center for Nonviolence.",
