      "title": "Witches Walk 2026",
      "location": "Bay St. Louis",
      "category": "Dining",
      "description": "Join the Coast's biggest costume party as Witches Walk celebrates its 14th year in beautiful Old Town Bay St. Louis! This beloved Halloween tradition brings hundreds of witches, warlocks, wizards, and magical revelers together for a weekend of costumes, contests, shopping, and spooky fun.Witches Walk is a free, family-friendly street party open to the public, but registration is required to participate in official games, contests, and special event activities.Event HighlightsHundreds of costumed witches and covens roaming Old Town Bay St. LouisFive exciting costume contests with prizesWingo card games with cash prizesShopping and dining specials throughout townDiscounted witches brews at participating bars and restaurantsUnique photo opportunities and Halloween-themed entertainmentFriday night Welcome Party at Cuz'sRegistration InformationAdvance Registration: $18 through September 30On-Site Registration: $25 on October 23-24, while supplies lastRegistration Includes:\u2013 Admission to the Friday Night Welcome Party at Cuz's\u2013 Official Witches Walk canvas tote bag\u2013 Entry into all five costume contests\u2013 Wingo card cash prize opportunities\u2013 Official Witches Walk souvenir cup for discounted beverages at participating establishments\u2013 Exclusive discounts at local businesses\u2013 Support for Bay St. Louis small businesses through the nonprofit Old Town Merchants AssociationOfficial Witches Walk T-shirts and tumblers are available for pre-order through the event website.Costume Contest CategoriesShow off your creativity for a chance to win prizes in categories including:Best CostumeBest BroomBest ShoeBest WandBest HatOverall costume winners will be recognized on the main stage.Experience the Magic of Bay St. LouisOn the Saturday before Halloween, the charming streets of Old Town Bay St. Louis transform into a magical gathering place filled with enchanting costumes, festive spirits, live entertainment, local shopping, and unforgettable memories. Whether you're a witch, wizard, warlock, or simply a Halloween enthusiast, everyone is invited to dress up and join the celebration.Don't miss one of the Coast's most popular Halloween events and a cherished Bay St. Louis tradition!",
