      "description": "Here Come the Mummies is an eight-piece funk-rock band of 5000 year-old Egyptian Mummies with a one-track mind. Their \"Terrifying Funk from Beyond the Grave\" is sure to get you into them (and possibly vice versa).Since their discovery, HCTM has been direct support for P-Funk, Al Green, Mavis Staples, KC and the Sunshine Band, and Cheap Trick; rocked Super Bowl Village; become a regular on The Bob and Tom Show; appeared on That\u2019s My Jam with Jimmy Fallon; played massive festivals like Summer Fest, Summer Camp, Bluesfest Byron Bay, Musikfest, and Suwannee Hulaween; and sold tickets by the thousands across large swaths of North America. Maybe that\u2019s why the ladies (and some dudes) can\u2019t stop losing their minds over these mayhem-inducing mavens of mirth.Some say they were cursed after deflowering a great Pharaoh\u2019s daughter. Others claim they are reincarnated Grammy-Winning studio musicians. Regardless, HCTM\u2019s mysterious personas, cunning song-craft, and unrelenting live show will bend your brain, and melt your face. Get ready! Here Come The Mummies.",
