      "date": "2026-11-07",
      "title": "The Magic of Gelli Plate Printing with Kathy Fejes",
      "location": "Bay St. Louis",
      "category": "Arts & Culture",
      "description": "Discover the magic of gelli plate printing with Kathy Fejes!In this hands-on workshop, you\u2019ll experiment with acrylic paints, stencils, textures, mark-making tools, paper, and fabric to create colorful, one-of-a-kind prints. Your finished pieces can be used for collage, greeting cards, painting backgrounds, wearable art, and more.Date: Saturday, November 7 Time: 10a \u2013 1pLocation: The Arts, Hancock County 405 Blaize Ave. Bay St. Louis, MSAges 18 and olderSpaces are limited \u2014 register early!https://tinyurl.com/GelliPlatePrinting-KathyKathy will demonstrate how to make a gel plate at home and teach you how to layer colors and patterns, print on different materials, care for your plate, and finish your completed prints.All materials are provided, and each student will receive a 5\" x 7\" gelli plate to use during class and take home!No drawing or painting experience is needed\u2014just come ready to explore, experiment, and enjoy the creative process.",
