      "description": "Art Without Walls (AWOW) returns to Bay St. Louis on Saturday, December 12, from 10 a.m. to 2 p.m. at the beautiful Mamie Hillery Art Center Sculpture Garden.This free, family-friendly outdoor arts event features local artists showcasing original artwork, jewelry, pottery, fiber arts, mixed media, and more. Enjoy live music and DJ entertainment throughout the day, plus exclusive discounts at participating Depot District businesses when you pick up an Art Without Walls sticker.Your Art Without Walls sticker can be picked up at the participating Bay St. Louis businesses:Lagarde's Fine Wines & SpiritsHen House of Bay St. LouisCaf\u00e9 BoneJourShow your sticker and enjoy special offers while exploring the historic Depot Arts District!Support local artists, connect with the community, and experience one of the Mississippi Gulf Coast's most creative events.Learn more about Art Without Walls 2026 by visiting https://tinyurl.com/ArtWithOutWalls-2026.",
