      "location": "Gulfport/Biloxi",
      "category": "Arts & Culture",
      "description": "Prepare to be enchanted with some of the world\u2019s finest Irish dancers and musicians bringing the spirit of Christmas to life, in a show that will make you laugh, cry, and sing into the night. Experience the magic as world-class performers blend melodic folk mash-ups, a cappella tap battles, and heartwarming storytelling into one truly unforgettable performance.Featuring former World Irish dance champions and stars from Lord of the Dance and Riverdance, A Celtic Christmas delivers a holiday celebration packed with Irish wit, traditional tunes and heartfelt ballads, alongside all your favorite carols. The show\u2019s electrifying rhythms and extraordinary talent promise an evening brimming with Irish charm and enthralling entertainment, all in one powerhouse event.",
